{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments, which may suggest higher risk for severe irAEs. The following are not exclusionary: vitiligo, childhood asthma that has resolved, type 1 diabetes, residual hypothyroidism that required only hormone replacement, or psoriasis that does not require systemic treatment.",
      "quote": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with an agent that blocks the PD-1/PD-L1 pathway.",
      "quote": "Prior treatment with an agent that blocks the PD-1/PD-L1 pathway.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with other systemic immune-modulating agents that was (a) within fewer than 4 weeks (28 days) of the enrollment date, or (b) associated with irAEs of any grade within 90 days prior to enrollment, or (c) associated with toxicity that resulted in discontinuation of the immune-modulating agent. Examples include therapeutic vaccines, cytokine treatments (other than G-CSF or erythropoietin), or agents targeting CTLA-4, 4-1BB, PI3K-delta, LAG3, or OX-40.",
      "quote": "Prior treatment with other systemic immune-modulating agents that was (a) within fewer than 4 weeks (28 days) of the enrollment date",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known history of brain metastasis(es) that may be considered active. Patients with previously treated brain metastases may participate if lesions are stable (no progression for at least 6 weeks on imaging), no new or enlarging metastases, and no immunosuppressive doses of systemic corticosteroids within 4 weeks of first dose.",
      "quote": "Known history of brain metastasis(es) that may be considered active",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of study drug. Brief courses of steroids (e.g., prophylaxis for imaging) are not excluded.",
      "quote": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of study drug",
      "thresholds": [
        {"test": "prednisone", "op": ">", "value": 10, "unit": "mg/day"}
      ]
    },
    {
      "kind": "exclusion",
      "text": "Active bacterial, viral, fungal or mycobacterial infection requiring therapy, including known HIV, or active HBV or HCV. Active HBV defined as positive surface antigen.",
      "quote": "Active bacterial, viral, fungal or mycobacterial infection requiring therapy",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of pneumonitis within the last 5 years. Inclusive of interstitial pneumonitis and active, non-infectious pneumonia, including interstitial lung disease.",
      "quote": "History of pneumonitis within the last 5 years.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any anticancer treatment (chemotherapy, targeted systemic therapy, photodynamic therapy), investigational, or standard of care, within 30 days of initial study drug administration or planned during study. Radiation must be discontinued at least 14 days prior. Bisphosphonates or denosumab not excluded.",
      "quote": "Any anticancer treatment (chemotherapy, targeted systemic therapy, photodynamic therapy), investigational, or standard of care, within 30 days of the initial administration of study drug",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments.",
      "quote": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Concurrent malignancy other than cervical cancer and/or history of malignancy other than cervical cancer within 3 years of first planned dose, except tumors with negligible risk (e.g., adequately treated cutaneous squamous cell carcinoma, basal cell carcinoma, ductal carcinoma in situ of breast). Hematologic malignancies excluded.",
      "quote": "Concurrent malignancy other than cervical cancer and/or history of malignancy other than cervical cancer within 3 years of date of first planned dose",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation.",
      "quote": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a history of solid organ transplant (prior corneal transplants may be allowed after discussion with medical monitor).",
      "quote": "Patients with a history of solid organ transplant",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any medical co-morbidity, physical examination finding, metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable due to high safety risks and/or potential to affect interpretation of results.",
      "quote": "Any medical co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Pregnant or breastfeeding women.",
      "quote": "Pregnant or breastfeeding women.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Women of childbearing potential who are unwilling to practice highly effective contraception prior to initial treatment, during study, and for at least 6 months after last dose. Highly effective methods include stable hormonal contraception, IUD, IUS, bilateral tubal ligation, vasectomized partner, or sexual abstinence. Periodic abstinence, withdrawal, spermicides only, and LAM are not acceptable.",
      "quote": "Women of childbearing potential* who are unwilling to practice highly effective contraception prior to the initial study drug treatment, during the study, and for at least 6 months after the last dose.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients committed to an institution by virtue of an order issued by either the judicial or the administrative authorities will be excluded from this study.",
      "quote": "Patients committed to an institution by virtue of an order issued by either the judicial or the administrative authorities will be excluded from this study.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with idelalisib.",
      "quote": "Prior treatment with idelalisib.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with live vaccines within 30 days of initial administration of study drug. Patients must not be treated with live vaccines during the study and up to 5 half-lives following the last dose.",
      "quote": "Prior treatment with live vaccines within 30 days of initial administration of study drug",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with prior treatment on any clinical trial within 30 days of the initial administration of study drug. Non-interventional and observational trials are acceptable.",
      "quote": "Patients with prior treatment on any clinical trial within 30 days of the initial administration of study drug.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Member of the clinical site study team and/or his or her immediate family.",
      "quote": "Member of the clinical site study team and/or his or her immediate family.",
      "thresholds": []
    }
  ]
}
